Here is the extended C# code that maintains the existing functionality while adding the option to export the report in CSV format:

```csharp
using System;
using System.IO;

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string filePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(filePath))
            {
                filePath = "report.csv";
            }

            try
            {
                using (StreamWriter writer = new StreamWriter(filePath))
                {
                    // Write CSV header
                    writer.WriteLine("Field,Value");

                    // Write CSV content based on report data
                    // Assuming SummaryReport has properties that can be serialized
                    // This is a simplified example; adjust based on actual SummaryReport structure
                    writer.WriteLine($"Date,{report.Date}");
                    writer.WriteLine($"Title,{report.Title}");
                    writer.WriteLine($"Content,{report.Content}");
                    writer.WriteLine($"Status,{report.Status}");
                }

                Console.WriteLine($"Report exported to CSV: {filePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }
}

// Placeholder for SummaryReport class to make the code compile
public class SummaryReport
{
    public DateTime Date { get; set; }
    public string Title { get; set; }
    public string Content { get; set; }
    public string Status { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nDate: {Date}\nStatus: {Status}\nContent: {Content}";
    }
}
